#!/usr/bin/env python3
"""Twenty-seventh pass: Milvus, and a vector store you can actually correct.

Run from the project root:   .venv/bin/python quality_pass27.py
Then rebuild the index:      .venv/bin/python -c "from app.retrieval.index import build; print(build())"

1. MILVUS, BEHIND AN INTERFACE.

   `app/retrieval/backend.py` puts one interface over the vector store and
   implements it twice. Milvus is the default; LanceDB stays, because a
   migration you cannot reverse is not a migration.

       VECTOR_BACKEND=milvus                      (default)
       ASOIA_MILVUS_URI=data/generated/milvus.db  embedded, nothing to run
       ASOIA_MILVUS_URI=http://localhost:19530    a Milvus standalone

   The URI decides embedded or server, the same way app/nim/client.py decides
   local NIM or hosted endpoint. Nothing in index.py or the review layer knows
   which store is behind it - before this pass they spoke LanceDB directly,
   which is why swapping it touched the review layer at all, and why it will
   not next time.

   NOT `MILVUS_URI`: pymilvus reads that name itself, at import, and rejects
   anything that is not http[s]://host:port - so pointing it at a Milvus Lite
   file makes `import pymilvus` raise before any project code runs.

2. EDITS WRITE THROUGH, BECAUSE THE STORE IS DERIVED.

   Every chunk is one row of `updates`, embedded. Edit a chunk in Milvus alone
   and it stops matching the record it cites - and nothing would catch it.
   `index_staleness` compared ids and counts, not text; `check_grounding` checks
   figures in the ANSWER against the TOOL RESULTS, never the other way round.
   You would get answers quoting text that is not in the database.

   So `app/retrieval/edit.py` changes the SOURCE and re-embeds that one chunk:

       updates.text  ->  re-embed  ->  upsert

   with the before and after kept. Four operations: edit, re-embed, exclude
   (index only, reversible), restore. There is no "add a chunk" - chunks exist
   because updates exist, and new updates arrive through the ingestion pipeline
   that applies the state machine and the conflict checks. There is no "delete
   the update" either: the log is append-only, and removing a technician's note
   is not an edit.

   `index_staleness` now also compares TEXT, which only became a possible
   divergence once chunks were editable, and which ids and counts cannot see.

3. THE EDITS ARE IN THE UI.

   Data & Retrieval -> Vector store -> "Edit this update", plus a new Edit log
   tab showing every change with what it said before.

THREE THINGS THE REGRESSION SUITE CAUGHT, ALL MINE

  * The audit trail went into `events`. That table is the repair-order LIFECYCLE
    log: every row is parsed through the `EventType` enum and folded into state,
    so three new type strings took out SEVEN of the fourteen answer checks with
    `ValueError: 'UPDATE_TEXT_EDITED' is not a valid EventType`. The docstring
    already said these were not lifecycle events; the code put them there
    anyway. They live in `index_audit` now, where they cannot reach the fold.

  * Milvus will not read a collection until it is loaded. A process that did not
    build the index found it in state 'released', and through the review layer's
    try/except that surfaced as an EMPTY STORE rather than an error - the worst
    kind of wrong answer. Every read now loads first, once per client.

  * All four edit buttons reported "Saved.", so excluding a chunk announced that
    the record and the index now agreed. True, and not what the button did.
"""
import sys, pathlib, ast

ROOT = pathlib.Path(".")
CHANGES = []


def edit(rel, old, new, label, skip_if=None):
    p = ROOT / rel
    if not p.exists():
        sys.exit(f"FAIL: {rel} not found - run from the project root")
    s = p.read_text()
    if skip_if and skip_if in s:
        CHANGES.append(f"  skip  {label} (already applied)")
        return
    n = s.count(old)
    if n != 1:
        sys.exit(f"FAIL: {label}: anchor found {n} times in {rel}, expected 1.\n"
                 "      NOTE: edits before this one HAVE been applied - this\n"
                 "      harness writes as it goes. Nothing is half-written.")
    p.write_text(s.replace(old, new, 1))
    CHANGES.append(f"  ok    {label}")


def write(rel, body, label):
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    if p.exists():
        if p.read_text() == body:
            CHANGES.append(f"  skip  {label} (already present)")
        else:
            p.write_text(body)
            CHANGES.append(f"  ok    {label} (replaced)")
        return
    p.write_text(body)
    CHANGES.append(f"  ok    {label}")


# ==================== 1. one interface, two stores

write('app/retrieval/backend.py',
      '"""One interface over the vector store, so nothing else knows which one it is.\n\nMilvus is the default. LanceDB is still here because it was the store for the\nfirst twenty-six passes and a migration you cannot reverse is not a migration.\n\n    VECTOR_BACKEND   "milvus" (default) or "lancedb"\n    ASOIA_MILVUS_URI   a file path  -> embedded Milvus Lite, no server\n                       http://host:19530 -> a Milvus standalone/cluster\n    ASOIA_MILVUS_COLLECTION  default "updates"\n\nNOT `MILVUS_URI`: pymilvus reads that name itself, at import, and rejects\nanything that is not `http[s]://host:port` - so setting it to a Milvus Lite file\npath makes `import pymilvus` raise before any of this runs. The ASOIA_ prefix the\nrest of the project uses avoids the collision as well as being consistent.\n    LANCE_URI        unchanged, for the lancedb backend\n\nThe URI decides whether Milvus runs embedded or against a server, exactly the way\n`app/nim/client.py` decides local NIM versus hosted endpoint. Embedded needs\nnothing installed and runs on a laptop; the server is a URI change, not a code\nchange, and the collection schema is identical either way.\n\nWHY THE INTERFACE IS THIS SHAPE\n\n`scan()` returns rows WITHOUT vectors and `get()` returns one row WITH its\nvector. That split is not tidiness: a 1024-float vector per row is about 8 KB, so\nlisting two thousand chunks to read their text used to move 15 MB of numbers that\nnothing looked at. The review browser calls `scan`, the detail view calls `get`.\n\nEvery method returns plain dicts with the same keys regardless of backend, so\n`app/review/store.py` and `app/retrieval/index.py` contain no per-store branching.\n"""\nfrom __future__ import annotations\n\nimport json\nimport math\nimport os\nimport threading\nfrom typing import Any\n\n# The fields carried for every chunk, besides the vector itself. Kept explicit so\n# both backends agree, and so a schema change is one list rather than a search.\nFIELDS = ["update_id", "ro_number", "staff_id", "staff_name", "at", "shift",\n          "text", "vehicle", "category", "concern", "vin"]\n\nCOLLECTION = os.environ.get("ASOIA_MILVUS_COLLECTION", "updates")\n\n\ndef _default_milvus_uri() -> str:\n    return os.environ.get("ASOIA_MILVUS_URI", "data/generated/milvus.db")\n\n\nclass BackendError(RuntimeError):\n    """Raised with an actionable message; callers turn it into a reported error."""\n\n\n# --------------------------------------------------------------------- Milvus\n\nclass MilvusBackend:\n    name = "milvus"\n\n    def __init__(self, uri: str | None = None, collection: str | None = None):\n        self.uri = uri or _default_milvus_uri()\n        self.collection = collection or COLLECTION\n        self._client = None\n        self._loaded = False\n        self._lock = threading.Lock()\n\n    @property\n    def mode(self) -> str:\n        return "server" if self.uri.startswith(("http://", "https://")) else "embedded"\n\n    def client(self):\n        if self._client is not None:\n            return self._client\n        with self._lock:\n            if self._client is not None:\n                return self._client\n            try:\n                from pymilvus import MilvusClient\n            except ImportError:\n                raise BackendError(\n                    "pymilvus is not installed - the Milvus backend needs it. "\n                    "uv pip install --python .venv \'pymilvus>=2.4\' milvus-lite"\n                ) from None\n            if self.mode == "embedded":\n                os.makedirs(os.path.dirname(os.path.abspath(self.uri)) or ".",\n                            exist_ok=True)\n            try:\n                self._client = MilvusClient(uri=self.uri)\n            except Exception as e:\n                raise BackendError(\n                    f"could not open Milvus at {self.uri} "\n                    f"({type(e).__name__}: {e})") from e\n            return self._client\n\n    def _load(self):\n        """Milvus will not read a collection until it is loaded into memory.\n\n        A process that did not build the index finds the collection in state\n        \'released\', and `query` then raises - or, through the review layer\'s\n        try/except, comes back as an empty store. That reads as "the index is\n        empty" rather than "this process has not loaded it", which is the worst\n        kind of wrong answer. Loading is idempotent and cheap after the first\n        call, so every read goes through here.\n        """\n        if self._loaded:\n            return\n        try:\n            c = self.client()\n            if self.collection in c.list_collections():\n                c.load_collection(self.collection)\n                self._loaded = True\n        except Exception:\n            pass\n\n    def exists(self) -> bool:\n        try:\n            return self.collection in self.client().list_collections()\n        except BackendError:\n            raise\n        except Exception:\n            return False\n\n    def create(self, dim: int) -> None:\n        """Drop and recreate. Building the index is a batch job, not an upsert loop."""\n        c = self.client()\n        if self.collection in c.list_collections():\n            c.drop_collection(self.collection)\n        from pymilvus import DataType\n        schema = c.create_schema(auto_id=False, enable_dynamic_field=True)\n        schema.add_field("pk", DataType.INT64, is_primary=True)\n        schema.add_field("vector", DataType.FLOAT_VECTOR, dim=dim)\n        # VARCHAR needs a max length; text is the only field that can be long.\n        schema.add_field("update_id", DataType.VARCHAR, max_length=64)\n        schema.add_field("ro_number", DataType.VARCHAR, max_length=32)\n        schema.add_field("staff_id", DataType.VARCHAR, max_length=32)\n        schema.add_field("staff_name", DataType.VARCHAR, max_length=128)\n        schema.add_field("at", DataType.VARCHAR, max_length=40)\n        schema.add_field("shift", DataType.VARCHAR, max_length=24)\n        schema.add_field("text", DataType.VARCHAR, max_length=8192)\n        schema.add_field("vehicle", DataType.VARCHAR, max_length=128)\n        schema.add_field("category", DataType.VARCHAR, max_length=64)\n        schema.add_field("concern", DataType.VARCHAR, max_length=2048)\n        schema.add_field("vin", DataType.VARCHAR, max_length=32)\n\n        index_params = c.prepare_index_params()\n        # COSINE because the embeddings are normalised and the reranker downstream\n        # cares about ordering, not absolute distance. AUTOINDEX lets Milvus pick\n        # FLAT for a collection this size, which is exact rather than approximate -\n        # at two thousand rows an ANN index would trade recall for nothing.\n        index_params.add_index(field_name="vector", index_type="AUTOINDEX",\n                               metric_type="COSINE")\n        c.create_collection(collection_name=self.collection, schema=schema,\n                            index_params=index_params)\n        self._loaded = False\n\n    @staticmethod\n    def _pk(update_id: str) -> int:\n        """A stable 63-bit primary key from the update id.\n\n        Milvus wants an int64 primary key and the natural key is a string. Hashing\n        keeps upsert idempotent - re-indexing one chunk replaces it rather than\n        duplicating it - without carrying a separate id map that could drift.\n        """\n        import hashlib\n        return int(hashlib.sha1(update_id.encode()).hexdigest()[:15], 16)\n\n    def upsert(self, rows: list[dict]) -> int:\n        if not rows:\n            return 0\n        c = self.client()\n        payload = []\n        for r in rows:\n            d = {"pk": self._pk(r["update_id"]), "vector": list(r["vector"])}\n            for f in FIELDS:\n                v = r.get(f)\n                d[f] = "" if v is None else str(v)\n            payload.append(d)\n        c.upsert(collection_name=self.collection, data=payload)\n        return len(payload)\n\n    def scan(self) -> list[dict]:\n        """Every row, without vectors."""\n        self._load()\n        c = self.client()\n        out = c.query(collection_name=self.collection, filter="pk >= 0",\n                      output_fields=FIELDS, limit=16384)\n        return [dict(r) for r in out]\n\n    def get(self, update_id: str) -> dict | None:\n        self._load()\n        c = self.client()\n        safe = update_id.replace(\'"\', \'\')\n        rows = c.query(collection_name=self.collection,\n                       filter=f\'update_id == "{safe}"\',\n                       output_fields=FIELDS + ["vector"], limit=1)\n        return dict(rows[0]) if rows else None\n\n    def search(self, vector: list[float], k: int,\n               ro_number: str | None = None) -> list[dict]:\n        self._load()\n        c = self.client()\n        flt = f\'ro_number == "{ro_number}"\' if ro_number else ""\n        res = c.search(collection_name=self.collection, data=[list(vector)],\n                       limit=k, filter=flt, output_fields=FIELDS,\n                       search_params={"metric_type": "COSINE"})\n        hits = []\n        for h in (res[0] if res else []):\n            row = dict(h.get("entity") or {})\n            # COSINE distance in Milvus is a similarity: higher is closer. The rest\n            # of the codebase reads `vector_score` as "what the vector stage said",\n            # and never compares it across backends, so it is passed through as is.\n            row["vector_score"] = h.get("distance")\n            hits.append(row)\n        return hits\n\n    def delete(self, update_ids: list[str]) -> int:\n        if not update_ids:\n            return 0\n        c = self.client()\n        c.delete(collection_name=self.collection,\n                 ids=[self._pk(u) for u in update_ids])\n        return len(update_ids)\n\n    def sample_vectors(self, n: int = 64) -> list[dict]:\n        """A few rows WITH their vectors, for the health check.\n\n        Separate from scan() because scan() deliberately drops the vector column;\n        a zero-norm vector is a failed embedding and nothing that reads text\n        would ever notice one.\n        """\n        self._load()\n        c = self.client()\n        return [dict(r) for r in c.query(\n            collection_name=self.collection, filter="pk >= 0",\n            output_fields=["update_id", "vector"], limit=max(1, n))]\n\n    def count(self) -> int | None:\n        try:\n            s = self.client().get_collection_stats(self.collection)\n            return int(s.get("row_count", 0))\n        except Exception:\n            try:\n                return len(self.scan())\n            except Exception:\n                return None\n\n    def dim(self) -> int | None:\n        try:\n            desc = self.client().describe_collection(self.collection)\n            for f in desc.get("fields", []):\n                if f.get("name") == "vector":\n                    return (f.get("params") or {}).get("dim")\n        except Exception:\n            pass\n        return None\n\n    def stats(self) -> dict:\n        return {"backend": "milvus", "mode": self.mode, "uri": self.uri,\n                "collection": self.collection}\n\n\n# -------------------------------------------------------------------- LanceDB\n\nclass LanceBackend:\n    """The store used up to pass 26. Kept so the migration is reversible."""\n    name = "lancedb"\n\n    def __init__(self, uri: str | None = None, table: str | None = None):\n        self.uri = uri or os.environ.get("LANCE_URI", "data/generated/lancedb")\n        self.collection = table or "updates"\n\n    mode = "embedded"\n\n    def _tbl(self):\n        try:\n            import lancedb\n        except ImportError:\n            raise BackendError(\n                "lancedb is not installed. uv pip install --python .venv lancedb"\n            ) from None\n        db = lancedb.connect(self.uri)\n        if self.collection not in db.table_names():\n            raise BackendError(\n                f"no \'{self.collection}\' table at {self.uri} - build the index first")\n        return db.open_table(self.collection)\n\n    def exists(self) -> bool:\n        try:\n            self._tbl()\n            return True\n        except Exception:\n            return False\n\n    def create(self, dim: int) -> None:      # lancedb creates on first write\n        self._pending_dim = dim\n\n    def upsert(self, rows: list[dict]) -> int:\n        import lancedb\n        db = lancedb.connect(self.uri)\n        data = [dict(r) for r in rows]\n        if self.collection in db.table_names():\n            tbl = db.open_table(self.collection)\n            ids = [r["update_id"] for r in data]\n            if ids:\n                quoted = ",".join("\'" + i.replace("\'", "") + "\'" for i in ids)\n                try:\n                    tbl.delete(f"update_id IN ({quoted})")\n                except Exception:\n                    pass\n            tbl.add(data)\n        else:\n            db.create_table(self.collection, data=data)\n        return len(data)\n\n    def drop(self) -> None:\n        import lancedb\n        db = lancedb.connect(self.uri)\n        if self.collection in db.table_names():\n            db.drop_table(self.collection)\n\n    def scan(self) -> list[dict]:\n        tbl = self._tbl()\n        try:\n            t = tbl.to_arrow()\n            if "vector" in t.column_names:\n                t = (t.drop_columns(["vector"]) if hasattr(t, "drop_columns")\n                     else t.drop(["vector"]))\n            return t.to_pylist()\n        except Exception:\n            rows = tbl.search().limit(100000).to_list()\n            for r in rows:\n                r.pop("vector", None)\n            return rows\n\n    def get(self, update_id: str) -> dict | None:\n        tbl = self._tbl()\n        safe = update_id.replace("\'", "")\n        try:\n            rows = tbl.search().where(f"update_id = \'{safe}\'").limit(1).to_list()\n        except Exception:\n            rows = [r for r in tbl.search().limit(100000).to_list()\n                    if r.get("update_id") == update_id]\n        return dict(rows[0]) if rows else None\n\n    def search(self, vector: list[float], k: int,\n               ro_number: str | None = None) -> list[dict]:\n        q = self._tbl().search(vector).limit(k)\n        if ro_number:\n            q = q.where(f"ro_number = \'{ro_number}\'")\n        hits = []\n        for h in q.to_list():\n            h.pop("vector", None)\n            h["vector_score"] = h.pop("_distance", None)\n            hits.append(h)\n        return hits\n\n    def delete(self, update_ids: list[str]) -> int:\n        if not update_ids:\n            return 0\n        quoted = ",".join("\'" + i.replace("\'", "") + "\'" for i in update_ids)\n        self._tbl().delete(f"update_id IN ({quoted})")\n        return len(update_ids)\n\n    def sample_vectors(self, n: int = 64) -> list[dict]:\n        rows = self._tbl().search().limit(max(1, n)).to_list()\n        return [{"update_id": r.get("update_id"), "vector": r.get("vector")}\n                for r in rows]\n\n    def count(self) -> int | None:\n        try:\n            return self._tbl().count_rows()\n        except Exception:\n            return None\n\n    def dim(self) -> int | None:\n        try:\n            one = self._tbl().search().limit(1).to_list()\n            v = one[0].get("vector") if one else None\n            return len(v) if v is not None else None\n        except Exception:\n            return None\n\n    def stats(self) -> dict:\n        return {"backend": "lancedb", "mode": "embedded", "uri": self.uri,\n                "collection": self.collection}\n\n\n# ------------------------------------------------------------------ selection\n\n_cached: dict[str, Any] = {}\n\n\ndef backend(name: str | None = None):\n    """The configured store. Cached, because opening Milvus Lite is not free."""\n    which = (name or os.environ.get("VECTOR_BACKEND", "milvus")).lower()\n    if which not in ("milvus", "lancedb"):\n        raise BackendError(\n            f"VECTOR_BACKEND={which!r} is not a store. Use \'milvus\' or \'lancedb\'.")\n    if which not in _cached:\n        _cached[which] = MilvusBackend() if which == "milvus" else LanceBackend()\n    return _cached[which]\n\n\ndef reset():\n    """Forget the cached backend - for tests, and after changing the URI."""\n    _cached.clear()\n\n\ndef norm(vector) -> float:\n    return math.sqrt(sum(float(x) * float(x) for x in vector))\n',
      'app/retrieval/backend.py  Milvus and LanceDB behind one interface')

write('app/retrieval/index.py',
      '"""Semantic search over technician updates: Milvus + nv-embedqa + nv-rerankqa.\n\nScope note: most manager questions ("what is the state of RO-x", "which are\nblocked", "what did EMP014 do") are STRUCTURED queries and are answered by the\ndeterministic tools, not by this. Retrieval serves the narrative slice - "has\nanyone seen this fault before", "what did the last technician say about it".\nBuilding the index is a one-off batch job; only the query embedding is per-call.\n\nThe store is behind `app/retrieval/backend.py`, so Milvus and LanceDB are a\nconfig change rather than a code change:\n\n    VECTOR_BACKEND=milvus        (default)\n    ASOIA_MILVUS_URI=data/generated/milvus.db      embedded, no server\n    ASOIA_MILVUS_URI=http://localhost:19530        a Milvus standalone\n\nNothing in this file knows which one is in use.\n"""\nfrom __future__ import annotations\nimport os, time\nfrom typing import Any\n\nfrom app.state import db as dbm\nfrom app.retrieval.backend import backend, BackendError\nfrom app.nim.client import (embed as nim_embed, embed_query as nim_embed_query,\n                            rerank as nim_rerank)\n\nBATCH = 64\n\n\ndef _rows(con, only: list[str] | None = None) -> list[dict]:\n    """Updates joined to their repair order, so retrieval can filter on metadata.\n\n    `only` restricts to specific update ids, which is what re-indexing a single\n    edited chunk needs - see app/retrieval/edit.py.\n    """\n    sql = """\n      SELECT u.update_id, u.ro_number, u.staff_id, u.at, u.shift, u.text,\n             s.name AS staff_name, s.role,\n             r.make, r.model, r.model_year, r.category, r.concern, r.vin\n      FROM updates u\n      LEFT JOIN staff s ON s.staff_id = u.staff_id\n      LEFT JOIN ros   r ON r.ro_number = u.ro_number\n    """\n    args: tuple = ()\n    if only:\n        sql += " WHERE u.update_id IN (%s)" % ",".join("?" * len(only))\n        args = tuple(only)\n    sql += " ORDER BY u.at"\n    out = []\n    for r in con.execute(sql, args):\n        d = dict(r)\n        d["vehicle"] = f"{d.pop(\'model_year\')} {d.pop(\'make\')} {d.pop(\'model\')}"\n        d.pop("role", None)\n        # Embed the update together with light context so the vector carries the\n        # vehicle and the job it belongs to, not just the sentence.\n        d["embed_text"] = (f"{d[\'vehicle\']} | {d[\'category\']} | "\n                           f"concern: {d[\'concern\']} | update: {d[\'text\']}")\n        out.append(d)\n    return out\n\n\ndef _embed_rows(rows: list[dict], progress: bool = False) -> int:\n    """Embed in place. Returns the dimension."""\n    vecs: list[list[float]] = []\n    for i in range(0, len(rows), BATCH):\n        chunk = [r["embed_text"] for r in rows[i:i + BATCH]]\n        vecs.extend(nim_embed(chunk, input_type="passage"))\n        if progress:\n            print(f"  embedded {min(i + BATCH, len(rows))}/{len(rows)}", end="\\r")\n    if progress and rows:\n        print()\n    for r, v in zip(rows, vecs):\n        r["vector"] = v\n        r.pop("embed_text", None)\n    return len(vecs[0]) if vecs else 0\n\n\ndef build(con=None, progress: bool = True, **_legacy) -> dict:\n    """Embed every update once and persist. Run after 01, before any search."""\n    con = con or dbm.connect()\n    rows = _rows(con)\n    if not rows:\n        return {"rows": 0, "error": "no updates to index - generate the dataset first"}\n    t0 = time.time()\n    dim = _embed_rows(rows, progress)\n    b = backend()\n    b.create(dim)\n    b.upsert(rows)\n    st = b.stats()\n    return {"rows": len(rows), "dim": dim, "seconds": round(time.time() - t0, 1),\n            **st}\n\n\ndef reindex(update_ids: list[str], con=None) -> dict:\n    """Re-embed and replace specific chunks. Used after an edit."""\n    con = con or dbm.connect()\n    rows = _rows(con, only=list(update_ids))\n    if not rows:\n        return {"reindexed": 0, "error": f"no updates found for {update_ids}"}\n    dim = _embed_rows(rows)\n    b = backend()\n    if not b.exists():\n        b.create(dim)\n    n = b.upsert(rows)\n    return {"reindexed": n, "dim": dim, "update_ids": [r["update_id"] for r in rows]}\n\n\ndef search(query: str, k: int = 8, rerank_to: int | None = 4,\n           ro_number: str | None = None, category: str | None = None,\n           **_legacy) -> list[dict]:\n    """Vector search, then rerank. Returns passages with update_id for citation."""\n    qv = nim_embed_query(query)\n    # Retrieve wide, rerank narrow. cand must be used for BOTH the limit and the\n    # slice below - slicing back to k would hide the wide pool from the reranker.\n    cand = max(k, (rerank_to or 0) * 3)\n    hits = backend().search(qv, k=cand, ro_number=ro_number)\n    if category:\n        hits = [h for h in hits if h.get("category") == category]\n\n    if rerank_to and len(hits) > 1:\n        try:\n            ranked = nim_rerank(query, [h["text"] for h in hits], top_n=rerank_to)\n            out = []\n            for r in ranked:\n                h = dict(hits[r["index"]])\n                h["rerank_score"] = r["score"]\n                out.append(h)\n            return out\n        except Exception as e:\n            for h in hits:\n                h["rerank_error"] = f"{type(e).__name__}"\n            return hits[:rerank_to]\n    return hits\n\n\ndef _dangling(update_ids: list[str]) -> list[str]:\n    """Which of these ids are not in the database. Cheap: one query, k ids."""\n    ids = [i for i in update_ids if i]\n    if not ids:\n        return []\n    try:\n        con = dbm.connect()\n        q = ",".join("?" * len(ids))\n        found = {r[0] for r in con.execute(\n            f"SELECT update_id FROM updates WHERE update_id IN ({q})", ids)}\n    except Exception:\n        return []                      # never fail a search over a health check\n    return [i for i in ids if i not in found]\n\n\ndef search_updates(query: str, k: int = 6, ro_number: str | None = None) -> dict:\n    """Agent-tool shape: grounded passages plus their citations.\n\n    The citations are checked against the database before they leave. An index\n    built from a previous dataset keeps working perfectly - it returns plausible\n    passages and cites update ids that no longer exist - and nothing downstream\n    would notice: `check_grounding` verifies figures in the ANSWER against the\n    TOOL RESULTS, never that a cited id resolves to a row. So it is verified\n    here, at the only place citations enter the system from outside the database.\n\n    The passages are still returned, flagged rather than dropped. Silently\n    removing them would hide a broken index behind slightly worse answers, which\n    is the failure mode this project keeps having to dig back out of.\n    """\n    hits = search(query, k=max(k * 3, 18), rerank_to=k, ro_number=ro_number)\n    cits = [h["update_id"] for h in hits]\n    out = {"query": query, "count": len(hits),\n           "passages": [{"update_id": h["update_id"], "ro_number": h["ro_number"],\n                         "at": h["at"], "by": h.get("staff_name") or h["staff_id"],\n                         "vehicle": h.get("vehicle"), "text": h["text"],\n                         "score": h.get("rerank_score", h.get("vector_score"))}\n                        for h in hits],\n           "citations": cits}\n    gone = _dangling(cits)\n    if gone:\n        out["stale_index"] = {\n            "dangling": gone,\n            "note": (f"the vector index is out of date: {len(gone)} of "\n                     f"{len(cits)} cited updates are not in the database. "\n                     f"Rebuild it with app.retrieval.index.build()")}\n    return out\n',
      'app/retrieval/index.py  retrieval through the backend, plus reindex()')


# ==================== 2. editing, written through to the record

write('app/retrieval/edit.py',
      '"""Editing the vector store, without letting it drift from the record.\n\nWHY EDITS WRITE THROUGH\n\nThe vector store is DERIVED. Every chunk is one row of `updates`, embedded. Edit\na chunk\'s text in Milvus directly and it no longer matches the update it cites -\nand nothing would catch it. `index_staleness()` compares ids and counts, not\ntext, and `check_grounding` checks figures in the answer against the tool\nresults, never the other way round. You would get answers quoting text that is\nnot in the database, which is the precise failure the citation checking in\n`search_updates` exists to prevent.\n\nSo an edit changes the SOURCE and re-embeds:\n\n    updates.text  ->  re-embed that one chunk  ->  upsert into the store\n\nand the old text is kept, because this project does not overwrite history. An\nedit is a correction, and a correction that hides what it corrected is worse than\nthe error.\n\nTHE AUDIT TRAIL IS ITS OWN TABLE, NOT THE EVENT LOG\n\nThe first version of this wrote edits into `events`. That table is the repair\norder LIFECYCLE log: `Event.from_row()` parses every row\'s type through the\n`EventType` enum and `fold()` consumes the result, so three new type strings took\nout seven of the fourteen answer checks and every read of an affected repair\norder with\n\n    ValueError: \'UPDATE_TEXT_EDITED\' is not a valid EventType\n\nThe docstring above already said these are not lifecycle events. They now live in\n`index_audit`, where they cannot reach the fold, and where nothing has to pretend\na data correction is something that happened in the workshop.\n\nWHAT IS AND IS NOT ALLOWED\n\n  edit_text      change an update\'s wording, re-embed, record the before/after\n  reindex        re-embed a chunk from the current record, no text change\n  exclude        drop a chunk from the index only; the update stays on file\n  restore        put an excluded chunk back\n\nThere is no "add a chunk". A chunk exists because an update exists; new updates\narrive through the Technician Update tab and the ingestion pipeline, which apply\nthe state machine and the conflict checks. A back door into the index would\nbypass both.\n\nDeleting an UPDATE is also not offered. The log is append-only; removing a\ntechnician\'s note is not an edit, it is a rewrite of what happened. `exclude`\ncovers the real need - a chunk that should not be retrievable - and is\nreversible.\n"""\nfrom __future__ import annotations\n\nimport json\nimport sqlite3\nfrom datetime import datetime\nfrom typing import Any\n\nfrom app.state import db as dbm\n\nEDIT_EVENT = "UPDATE_TEXT_EDITED"\nEXCLUDE_EVENT = "UPDATE_INDEX_EXCLUDED"\nRESTORE_EVENT = "UPDATE_INDEX_RESTORED"\n\n_DDL = """\nCREATE TABLE IF NOT EXISTS index_exclusions (\n  update_id TEXT PRIMARY KEY,\n  at TEXT NOT NULL,\n  actor_id TEXT,\n  reason TEXT\n);\nCREATE TABLE IF NOT EXISTS index_audit (\n  audit_id INTEGER PRIMARY KEY AUTOINCREMENT,\n  update_id TEXT NOT NULL,\n  ro_number TEXT,\n  kind TEXT NOT NULL,\n  at TEXT NOT NULL,\n  actor_id TEXT,\n  payload TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_index_audit_update ON index_audit(update_id, at);\n"""\n\n\ndef _con(con: sqlite3.Connection | None = None) -> sqlite3.Connection:\n    return con if con is not None else dbm.connect()\n\n\ndef ensure_tables(con: sqlite3.Connection | None = None) -> None:\n    c = _con(con)\n    c.executescript(_DDL)\n    c.commit()\n\n\ndef _record(con, update_id: str, kind: str, actor_id: str, payload: dict) -> int | None:\n    """Append to the edit audit trail. Never raises - an edit must not fail over its log.\n\n    Deliberately NOT the `events` table. That one is the repair order lifecycle\n    log: every row is parsed through `EventType` and folded into state, so an\n    unknown type string breaks every read of that repair order. A data\n    correction is not something that happened to the vehicle.\n    """\n    try:\n        ensure_tables(con)\n        row = con.execute("SELECT ro_number FROM updates WHERE update_id = ?",\n                          (update_id,)).fetchone()\n        from app.state.clock import event_time\n        cur = con.execute(\n            "INSERT INTO index_audit (update_id, ro_number, kind, at, actor_id, "\n            "payload) VALUES (?,?,?,?,?,?)",\n            (update_id, row[0] if row else None, kind,\n             event_time().isoformat(timespec="seconds"), actor_id,\n             json.dumps(payload, default=str)))\n        con.commit()\n        return cur.lastrowid\n    except Exception:\n        return None\n\n\ndef get_update(update_id: str, con: sqlite3.Connection | None = None) -> dict | None:\n    c = _con(con)\n    r = c.execute(\n        "SELECT u.update_id, u.ro_number, u.staff_id, u.at, u.shift, u.text, "\n        "COALESCE(s.name, u.staff_id) AS staff_name FROM updates u "\n        "LEFT JOIN staff s ON s.staff_id = u.staff_id WHERE u.update_id = ?",\n        (update_id,)).fetchone()\n    return dict(r) if r else None\n\n\ndef edit_text(update_id: str, new_text: str, actor_id: str = "REVIEWER",\n              con: sqlite3.Connection | None = None) -> dict:\n    """Change an update\'s text, re-embed its chunk, and record what changed."""\n    c = _con(con)\n    cur = get_update(update_id, c)\n    if not cur:\n        return {"ok": False, "error": f"no update {update_id}"}\n    new_text = (new_text or "").strip()\n    if not new_text:\n        return {"ok": False, "error": "the text cannot be empty - use exclude "\n                                      "to take a chunk out of the index"}\n    if new_text == cur["text"]:\n        return {"ok": True, "changed": False, "update_id": update_id,\n                "note": "the text is unchanged; nothing was written"}\n\n    before = cur["text"]\n    try:\n        c.execute("UPDATE updates SET text = ? WHERE update_id = ?",\n                  (new_text, update_id))\n        c.commit()\n    except Exception as e:\n        return {"ok": False, "error": f"could not write the update: "\n                                      f"{type(e).__name__}: {e}"}\n\n    ev = _record(c, update_id, EDIT_EVENT, actor_id,\n                 {"before": before, "after": new_text})\n\n    # Re-embed. If this fails the record is already correct and the index is\n    # stale by exactly one chunk, which index_staleness() will report - so say so\n    # rather than rolling back a correction the user asked for.\n    try:\n        from app.retrieval.index import reindex\n        r = reindex([update_id], con=c)\n        reindexed = bool(r.get("reindexed"))\n        err = r.get("error")\n    except Exception as e:\n        reindexed, err = False, f"{type(e).__name__}: {e}"\n\n    out = {"ok": True, "changed": True, "update_id": update_id,\n           "before": before, "after": new_text, "audit_id": ev,\n           "reindexed": reindexed}\n    if not reindexed:\n        out["warning"] = (\n            f"the record was updated but the chunk could not be re-embedded "\n            f"({err}). The index now disagrees with the database for this one "\n            f"update; /health and the review Overview will report it. Rebuild "\n            f"with app.retrieval.index.reindex([\'{update_id}\']) once the "\n            f"embedding endpoint is reachable.")\n    return out\n\n\ndef reindex_one(update_id: str, con: sqlite3.Connection | None = None) -> dict:\n    """Re-embed a chunk from the current record. No text change."""\n    c = _con(con)\n    if not get_update(update_id, c):\n        return {"ok": False, "error": f"no update {update_id}"}\n    try:\n        from app.retrieval.index import reindex\n        r = reindex([update_id], con=c)\n    except Exception as e:\n        return {"ok": False, "error": f"{type(e).__name__}: {e}"}\n    if r.get("error"):\n        return {"ok": False, "error": r["error"]}\n    return {"ok": True, "update_id": update_id, "dim": r.get("dim")}\n\n\ndef exclude(update_id: str, reason: str = "", actor_id: str = "REVIEWER",\n            con: sqlite3.Connection | None = None) -> dict:\n    """Remove a chunk from the index. The update itself stays on file."""\n    c = _con(con)\n    if not get_update(update_id, c):\n        return {"ok": False, "error": f"no update {update_id}"}\n    ensure_tables(c)\n    try:\n        from app.retrieval.backend import backend\n        backend().delete([update_id])\n    except Exception as e:\n        return {"ok": False, "error": f"could not remove it from the index: "\n                                      f"{type(e).__name__}: {e}"}\n    c.execute("INSERT OR REPLACE INTO index_exclusions (update_id, at, actor_id, "\n              "reason) VALUES (?,?,?,?)",\n              (update_id, datetime.now().isoformat(timespec="seconds"), actor_id,\n               reason))\n    c.commit()\n    ev = _record(c, update_id, EXCLUDE_EVENT, actor_id, {"reason": reason})\n    return {"ok": True, "update_id": update_id, "audit_id": ev,\n            "note": "the update is still on file; only its chunk was removed. "\n                    "A full rebuild would bring it back unless it stays excluded."}\n\n\ndef restore(update_id: str, actor_id: str = "REVIEWER",\n            con: sqlite3.Connection | None = None) -> dict:\n    """Put an excluded chunk back into the index."""\n    c = _con(con)\n    ensure_tables(c)\n    if not get_update(update_id, c):\n        return {"ok": False, "error": f"no update {update_id}"}\n    try:\n        from app.retrieval.index import reindex\n        r = reindex([update_id], con=c)\n    except Exception as e:\n        return {"ok": False, "error": f"{type(e).__name__}: {e}"}\n    if r.get("error"):\n        return {"ok": False, "error": r["error"]}\n    c.execute("DELETE FROM index_exclusions WHERE update_id = ?", (update_id,))\n    c.commit()\n    ev = _record(c, update_id, RESTORE_EVENT, actor_id, {})\n    return {"ok": True, "update_id": update_id, "audit_id": ev}\n\n\ndef exclusions(con: sqlite3.Connection | None = None) -> list[dict]:\n    c = _con(con)\n    ensure_tables(c)\n    return [dict(r) for r in c.execute(\n        "SELECT update_id, at, actor_id, reason FROM index_exclusions ORDER BY at DESC")]\n\n\ndef history(update_id: str, con: sqlite3.Connection | None = None) -> list[dict]:\n    """Every edit, exclusion and restore recorded against one update."""\n    c = _con(con)\n    ensure_tables(c)\n    rows = []\n    for r in c.execute(\n            "SELECT audit_id, kind, at, actor_id, payload FROM index_audit "\n            "WHERE update_id = ? ORDER BY at DESC, audit_id DESC", (update_id,)):\n        d = dict(r)\n        try:\n            d["payload"] = json.loads(d["payload"])\n        except (TypeError, ValueError):\n            pass\n        rows.append(d)\n    return rows\n\n\ndef recent_edits(limit: int = 100, con: sqlite3.Connection | None = None) -> list[dict]:\n    """The whole audit trail, newest first - for the review screen."""\n    c = _con(con)\n    ensure_tables(c)\n    rows = []\n    for r in c.execute(\n            "SELECT audit_id, update_id, ro_number, kind, at, actor_id, payload "\n            "FROM index_audit ORDER BY audit_id DESC LIMIT ?", (limit,)):\n        d = dict(r)\n        try:\n            d["payload"] = json.loads(d["payload"])\n        except (TypeError, ValueError):\n            pass\n        rows.append(d)\n    return rows\n',
      'app/retrieval/edit.py  edit, re-embed, exclude, restore - with an audit trail')

edit('app/review/store.py',
     'NO_LANCEDB = ("lancedb is not installed - the vector views need it. "\n              "uv pip install --python .venv lancedb")\n\n\ndef _table(uri: str | None = None):\n    try:\n        import lancedb\n    except ImportError:\n        raise RuntimeError(NO_LANCEDB) from None\n    db = lancedb.connect(uri or LANCE_URI)\n    if TABLE not in db.table_names():\n        raise RuntimeError(\n            f"no \'{TABLE}\' table at {uri or LANCE_URI} - build the index first: "\n            f".venv/bin/python -c \'from app.retrieval.index import build; print(build())\'")\n    return db.open_table(TABLE)\n\n\ndef _scan(tbl, drop_vector: bool = True) -> list[dict]:\n    """Every row, as dicts. Drops the vector COLUMN rather than the values.\n\n    `to_list()` builds a Python list of 1024 floats for every row and then the\n    caller throws them away - about 8 KB of object churn per row to read a text\n    field. Arrow drops the column before any of it becomes Python.\n    """\n    try:\n        t = tbl.to_arrow()\n        if drop_vector and "vector" in t.column_names:\n            t = (t.drop_columns(["vector"]) if hasattr(t, "drop_columns")\n                 else t.drop(["vector"]))\n        return t.to_pylist()\n    except Exception:\n        rows = tbl.search().limit(100_000).to_list()\n        if drop_vector:\n            for r in rows:\n                r.pop("vector", None)\n        return rows\n\n\ndef index_health(sample: int = 64, uri: str | None = None) -> dict:\n    """Sample vectors and check they are real. A zero norm is a failed embedding.\n\n    Deliberately a sampled, separate call: the browse views never touch vectors, so\n    nothing else in this module would ever notice an index full of zeros.\n    """\n    try:\n        tbl = _table(uri)\n        recs = tbl.search().limit(sample).to_list()\n    except Exception as e:\n        return {"error": str(e)}\n    norms = []\n    for r in recs:\n        v = r.get("vector")\n        if v is None:\n            continue\n        norms.append(math.sqrt(sum(float(x) * float(x) for x in v)))\n    if not norms:\n        return {"sampled": 0, "error": "no vectors in the sample"}\n    zero = sum(1 for n in norms if n < 1e-9)\n    return {"sampled": len(norms), "zero_norm": zero,\n            "min_norm": round(min(norms), 6), "max_norm": round(max(norms), 6),\n            "mean_norm": round(sum(norms) / len(norms), 6),\n            "ok": zero == 0}\n\n\ndef index_stats(uri: str | None = None) -> dict:\n    """Is there an index, how big, how wide, and how old."""\n    uri = uri or LANCE_URI\n    out: dict[str, Any] = {"uri": uri, "table": TABLE, "exists": False}\n    try:\n        tbl = _table(uri)\n    except Exception as e:\n        out["error"] = str(e)\n        return out\n    out["exists"] = True\n    try:\n        out["rows"] = tbl.count_rows()\n    except Exception:\n        out["rows"] = None\n    try:\n        names = [f.name for f in tbl.schema]\n        out["columns"] = names\n        for f in tbl.schema:\n            if f.name == "vector":\n                out["dim"] = getattr(f.type, "list_size", None) or \\\n                             getattr(getattr(f.type, "value_type", None), "bit_width", None)\n    except Exception:\n        pass\n    if not out.get("dim"):                        # ask a row, if the schema would not say\n        try:\n            one = tbl.search().limit(1).to_list()\n            if one and one[0].get("vector") is not None:\n                out["dim"] = len(one[0]["vector"])\n        except Exception:\n            pass\n    try:\n        p = os.path.join(uri, f"{TABLE}.lance")\n        if os.path.exists(p):\n            out["built_at"] = datetime.fromtimestamp(os.path.getmtime(p)).isoformat(\n                timespec="seconds")\n            out["bytes"] = sum(\n                os.path.getsize(os.path.join(dp, f))\n                for dp, _, fs in os.walk(p) for f in fs)\n    except Exception:\n        pass\n    try:\n        out["staleness"] = index_staleness(uri=uri)\n    except Exception as e:\n        out["staleness"] = {"ok": None, "reasons": [f"{type(e).__name__}: {e}"]}\n    return out\n\n\ndef index_staleness(uri: str | None = None, con: sqlite3.Connection | None = None) -> dict:\n    """Does the vector index still match the database?\n\n    This is the one failure in the system that produces confident, well-formed,\n    fully "grounded" answers citing records that do not exist. `check_grounding`\n    verifies that figures and repair-order references in the ANSWER appear in the\n    TOOL RESULTS; nothing has ever checked that a cited update id resolves to a\n    real row. Regenerate the data without rebuilding the index and retrieval goes\n    on serving passages from the old dataset, citing ids that are gone, and every\n    check passes.\n\n    Three drifts, in increasing order of how much they matter:\n\n        the counts differ            built from a different dataset\n        the newest update is absent  recent work is invisible to search\n        cited ids do not resolve     answers cite records that are not there\n    """\n    c = _con(con)\n    out: dict[str, Any] = {"ok": True, "reasons": []}\n    try:\n        db_updates = c.execute("SELECT COUNT(*) FROM updates").fetchone()[0]\n    except Exception as e:\n        return {"ok": None, "reasons": [f"no updates table: {type(e).__name__}"]}\n    out["database_updates"] = db_updates\n    try:\n        tbl = _table(uri)\n        rows = _scan(tbl)\n    except Exception as e:\n        return {"ok": None, "reasons": [str(e)], "database_updates": db_updates}\n\n    out["index_rows"] = len(rows)\n    if len(rows) != db_updates:\n        out["ok"] = False\n        out["reasons"].append(\n            f"the index holds {len(rows)} chunks and the database has "\n            f"{db_updates} updates")\n\n    indexed = {r.get("update_id") for r in rows if r.get("update_id")}\n    known = {r[0] for r in c.execute("SELECT update_id FROM updates")}\n    dangling = sorted(indexed - known)\n    out["dangling"] = len(dangling)\n    out["dangling_sample"] = dangling[:5]\n    if dangling:\n        out["ok"] = False\n        out["reasons"].append(\n            f"{len(dangling)} indexed chunk(s) cite update ids that are not in "\n            f"the database - answers would cite records that do not exist")\n\n    unindexed = sorted(known - indexed)\n    out["unindexed"] = len(unindexed)\n    if unindexed:\n        out["ok"] = False\n        out["reasons"].append(\n            f"{len(unindexed)} update(s) are not in the index and cannot be "\n            f"found by semantic search")\n\n    if not out["ok"]:\n        out["fix"] = (".venv/bin/python -c \'from app.retrieval.index import build; "\n                      "print(build())\'")\n    return out\n\n\ndef chunks(ro_number: str | None = None, text: str | None = None,\n           limit: int = 100, offset: int = 0, uri: str | None = None) -> dict:\n    """Browse what is IN the vector store, without pulling the vectors themselves.\n\n    A 1024-float vector per row is about 8 KB; a hundred of them is most of a\n    megabyte of numbers nobody reads, so the vector column is dropped in Arrow\n    before any of it becomes Python. `index_health()` samples the vectors\n    themselves, and `chunk()` shows one in full.\n    """\n    try:\n        tbl = _table(uri)\n    except Exception as e:\n        return {"error": str(e), "rows": [], "total": 0}\n    try:\n        recs = _scan(tbl)\n    except Exception as e:\n        return {"error": f"{type(e).__name__}: {e}", "rows": [], "total": 0}\n\n    out = []\n    for r in recs:\n        if ro_number and r.get("ro_number") != ro_number:\n            continue\n        if text and text.lower() not in (r.get("text") or "").lower():\n            continue\n        r.pop("vector", None)\n        r.pop("_distance", None)\n        out.append(r)\n    out.sort(key=lambda r: r.get("at") or "", reverse=True)\n    return {"total": len(out), "returned": min(limit, max(0, len(out) - offset)),\n            "offset": offset, "rows": out[offset:offset + limit]}\n\n\ndef chunk(update_id: str, preview_dims: int = 12, uri: str | None = None) -> dict:\n    """One chunk in full: its text, its metadata, and the front of its vector."""\n    try:\n        tbl = _table(uri)\n    except Exception as e:\n        return {"error": str(e)}\n    try:\n        safe = update_id.replace("\'", "\'\'")\n        try:\n            recs = tbl.search().where(f"update_id = \'{safe}\'").limit(1).to_list()\n        except Exception:      # older lancedb: no filter on an empty search\n            recs = [r for r in tbl.search().limit(100_000).to_list()\n                    if r.get("update_id") == update_id]\n    except Exception as e:\n        return {"error": f"{type(e).__name__}: {e}"}\n    if not recs:\n        return {"error": f"no chunk for update {update_id}"}\n    r = dict(recs[0])\n    v = r.pop("vector", None)\n    r.pop("_distance", None)\n    if v is not None:\n        v = [float(x) for x in v]\n        r["dim"] = len(v)\n        r["norm"] = round(math.sqrt(sum(x * x for x in v)), 6)\n        r["vector_preview"] = [round(x, 5) for x in v[:preview_dims]]\n    return r\n\n\n# ------------------------------------------------------- what retrieval actually did\n\ndef retrieval_trace(query: str, retrieve_n: int = RETRIEVE_N,\n                    rerank_n: int = RERANK_N, ro_number: str | None = None,\n                    uri: str | None = None) -> dict:\n    """Both stages of a real search, so the reranker\'s contribution is visible.\n\n    `search_updates` returns six passages and nothing about how they were chosen.\n    This runs the same two calls - the same query embedding, the same wide retrieve,\n    the same rerank - and keeps the intermediate stage, with each passage\'s movement\n    between the two.\n\n    It mirrors app/retrieval/index.py rather than sharing its code, so that it can\n    keep the stage that `search` throws away. test_review.py asserts the two agree\n    on the final citations; if they ever diverge, that test is what says so.\n    """\n    from app.nim.client import embed_query as nim_embed_query, rerank as nim_rerank\n    out: dict[str, Any] = {"query": query, "retrieve_n": retrieve_n,\n                           "rerank_n": rerank_n, "ro_number": ro_number}\n    try:\n        tbl = _table(uri)\n    except Exception as e:\n        return {**out, "error": str(e)}\n\n    t0 = time.perf_counter()\n    try:\n        qv = nim_embed_query(query)\n    except Exception as e:\n        return {**out, "error": f"embedding failed - {type(e).__name__}: {e}"}\n    out["embed_ms"] = round((time.perf_counter() - t0) * 1000, 1)\n    out["query_dim"] = len(qv)\n\n    t1 = time.perf_counter()\n    try:\n        q = tbl.search(qv).limit(retrieve_n)\n        if ro_number:\n            q = q.where(f"ro_number = \'{ro_number}\'")\n        hits = q.to_list()\n    except Exception as e:\n        return {**out, "error": f"vector search failed - {type(e).__name__}: {e}"}\n    out["search_ms"] = round((time.perf_counter() - t1) * 1000, 1)\n\n    retrieved = []\n    for i, h in enumerate(hits):\n        h.pop("vector", None)\n        retrieved.append({\n            "rank": i + 1, "update_id": h.get("update_id"),\n            "ro_number": h.get("ro_number"), "at": h.get("at"),\n            "by": h.get("staff_name") or h.get("staff_id"),\n            "vehicle": h.get("vehicle"), "text": h.get("text"),\n            "vector_score": h.pop("_distance", None)})\n    out["retrieved"] = retrieved\n\n    if not retrieved or rerank_n <= 0:\n        out["reranked"] = []\n        return out\n\n    t2 = time.perf_counter()\n    try:\n        ranked = nim_rerank(query, [r["text"] for r in retrieved], top_n=rerank_n)\n    except Exception as e:\n        out["rerank_error"] = f"{type(e).__name__}: {e}"\n        out["reranked"] = retrieved[:rerank_n]\n        return out\n    out["rerank_ms"] = round((time.perf_counter() - t2) * 1000, 1)\n\n    reranked = []\n    for new_rank, r in enumerate(ranked, 1):\n        src = dict(retrieved[r["index"]])\n        src["rerank_score"] = r["score"]\n        src["vector_rank"] = src.pop("rank")\n        src["rank"] = new_rank\n        src["moved"] = src["vector_rank"] - new_rank      # positive = promoted\n        reranked.append(src)\n    out["reranked"] = reranked\n\n    kept = {r["update_id"] for r in reranked}\n    out["promoted"] = [r for r in reranked if r["moved"] > 0]\n    out["dropped"] = [r for r in retrieved[:rerank_n] if r["update_id"] not in kept]\n    out["citations"] = [r["update_id"] for r in reranked]\n    return out',
     '# The store is behind app/retrieval/backend.py, so none of these functions know\n# whether they are reading Milvus or LanceDB. Before pass 27 they spoke LanceDB\n# directly, which is why swapping the store meant touching the review layer at\n# all - and why it will not next time.\n\ndef _backend():\n    from app.retrieval.backend import backend\n    return backend()\n\n\ndef _scan() -> list[dict]:\n    """Every row, without vectors - the vector column never becomes Python."""\n    return _backend().scan()\n\n\ndef index_health(sample: int = 64, uri: str | None = None) -> dict:\n    """Sample vectors and check they are real. A zero norm is a failed embedding.\n\n    Deliberately a sampled, separate call: the browse views never touch vectors,\n    so nothing else in this module would ever notice an index full of zeros.\n    """\n    try:\n        recs = _backend().sample_vectors(sample)\n    except Exception as e:\n        return {"error": str(e)}\n    norms = []\n    for r in recs:\n        v = r.get("vector")\n        if v is None:\n            continue\n        norms.append(math.sqrt(sum(float(x) * float(x) for x in v)))\n    if not norms:\n        return {"sampled": 0, "error": "no vectors in the sample"}\n    zero = sum(1 for n in norms if n < 1e-9)\n    return {"sampled": len(norms), "zero_norm": zero,\n            "min_norm": round(min(norms), 6), "max_norm": round(max(norms), 6),\n            "mean_norm": round(sum(norms) / len(norms), 6),\n            "ok": zero == 0}\n\n\ndef index_stats(uri: str | None = None) -> dict:\n    """Which store, where, how big, how wide - and whether it matches the data."""\n    b = _backend()\n    out: dict[str, Any] = {**b.stats(), "exists": False}\n    try:\n        out["exists"] = b.exists()\n    except Exception as e:\n        out["error"] = str(e)\n        return out\n    if not out["exists"]:\n        out["error"] = (f"no \'{b.collection}\' collection at {b.uri} - build the "\n                        f"index first: .venv/bin/python -c "\n                        f"\'from app.retrieval.index import build; print(build())\'")\n        return out\n    try:\n        out["rows"] = b.count()\n    except Exception:\n        out["rows"] = None\n    try:\n        out["dim"] = b.dim()\n    except Exception:\n        out["dim"] = None\n    try:\n        p = b.uri\n        if os.path.exists(p):\n            out["built_at"] = datetime.fromtimestamp(os.path.getmtime(p)).isoformat(\n                timespec="seconds")\n            out["bytes"] = (os.path.getsize(p) if os.path.isfile(p) else\n                            sum(os.path.getsize(os.path.join(dp, f))\n                                for dp, _, fs in os.walk(p) for f in fs))\n    except Exception:\n        pass\n    try:\n        out["staleness"] = index_staleness()\n    except Exception as e:\n        out["staleness"] = {"ok": None, "reasons": [f"{type(e).__name__}: {e}"]}\n    return out\n\n\ndef index_staleness(uri: str | None = None, con: sqlite3.Connection | None = None) -> dict:\n    """Does the vector index still match the database?\n\n    This is the one failure in the system that produces confident, well-formed,\n    fully "grounded" answers citing records that do not exist. `check_grounding`\n    verifies that figures and repair-order references in the ANSWER appear in the\n    TOOL RESULTS; nothing has ever checked that a cited update id resolves to a\n    real row. Regenerate the data without rebuilding the index and retrieval goes\n    on serving passages from the old dataset, citing ids that are gone, and every\n    check passes.\n\n    Four drifts, in increasing order of how much they matter:\n\n        the counts differ            built from a different dataset\n        the newest update is absent  recent work is invisible to search\n        cited ids do not resolve     answers cite records that are not there\n        the TEXT differs             answers quote wording that is not on file\n\n    The last one is new in pass 27 and only became possible once chunks were\n    editable: an edit that writes to the database but fails to re-embed leaves\n    the index quoting the old wording, and ids and counts both still match.\n    """\n    c = _con(con)\n    out: dict[str, Any] = {"ok": True, "reasons": []}\n    try:\n        db_updates = c.execute("SELECT COUNT(*) FROM updates").fetchone()[0]\n    except Exception as e:\n        return {"ok": None, "reasons": [f"no updates table: {type(e).__name__}"]}\n    out["database_updates"] = db_updates\n    try:\n        rows = _scan()\n    except Exception as e:\n        return {"ok": None, "reasons": [str(e)], "database_updates": db_updates}\n\n    out["index_rows"] = len(rows)\n    excluded = set()\n    try:\n        from app.retrieval.edit import exclusions\n        excluded = {e["update_id"] for e in exclusions(c)}\n    except Exception:\n        pass\n    out["excluded"] = len(excluded)\n\n    if len(rows) + len(excluded) != db_updates:\n        out["ok"] = False\n        out["reasons"].append(\n            f"the index holds {len(rows)} chunks and the database has "\n            f"{db_updates} updates"\n            + (f" ({len(excluded)} deliberately excluded)" if excluded else ""))\n\n    indexed = {r.get("update_id") for r in rows if r.get("update_id")}\n    known = {r[0] for r in c.execute("SELECT update_id FROM updates")}\n    dangling = sorted(indexed - known)\n    out["dangling"] = len(dangling)\n    out["dangling_sample"] = dangling[:5]\n    if dangling:\n        out["ok"] = False\n        out["reasons"].append(\n            f"{len(dangling)} indexed chunk(s) cite update ids that are not in "\n            f"the database - answers would cite records that do not exist")\n\n    unindexed = sorted(known - indexed - excluded)\n    out["unindexed"] = len(unindexed)\n    if unindexed:\n        out["ok"] = False\n        out["reasons"].append(\n            f"{len(unindexed)} update(s) are not in the index and cannot be "\n            f"found by semantic search")\n\n    # Text drift: only checkable for ids present in both, and only worth checking\n    # since chunks became editable.\n    drifted = []\n    try:\n        db_text = {r[0]: r[1] for r in c.execute(\n            "SELECT update_id, text FROM updates")}\n        for r in rows:\n            uid = r.get("update_id")\n            if uid in db_text and (r.get("text") or "") != (db_text[uid] or ""):\n                drifted.append(uid)\n    except Exception:\n        pass\n    out["text_drift"] = len(drifted)\n    out["text_drift_sample"] = drifted[:5]\n    if drifted:\n        out["ok"] = False\n        out["reasons"].append(\n            f"{len(drifted)} chunk(s) hold different text from the update they "\n            f"come from - an edit was written but not re-embedded, so answers "\n            f"would quote wording that is not on file")\n\n    if not out["ok"]:\n        out["fix"] = (".venv/bin/python -c \'from app.retrieval.index import build; "\n                      "print(build())\'")\n    return out\n\n\ndef chunks(ro_number: str | None = None, text: str | None = None,\n           limit: int = 100, offset: int = 0, uri: str | None = None) -> dict:\n    """Browse what is IN the vector store, without pulling the vectors themselves.\n\n    A 1024-float vector per row is about 8 KB; a hundred of them is most of a\n    megabyte of numbers nobody reads, so the backend drops the vector column\n    before any of it becomes Python. `index_health()` samples the vectors\n    themselves, and `chunk()` shows one.\n    """\n    try:\n        recs = _scan()\n    except Exception as e:\n        return {"error": str(e), "rows": [], "total": 0}\n\n    out = []\n    for r in recs:\n        if ro_number and r.get("ro_number") != ro_number:\n            continue\n        if text and text.lower() not in (r.get("text") or "").lower():\n            continue\n        r.pop("vector", None)\n        r.pop("_distance", None)\n        out.append(r)\n    out.sort(key=lambda r: r.get("at") or "", reverse=True)\n    return {"total": len(out), "returned": min(limit, max(0, len(out) - offset)),\n            "offset": offset, "rows": out[offset:offset + limit]}\n\n\ndef chunk(update_id: str, preview_dims: int = 12, uri: str | None = None) -> dict:\n    """One chunk in full: its text, its metadata, and the front of its vector.\n\n    Also reports whether the chunk\'s text still matches the update it came from,\n    because that is the one divergence the id-and-count checks cannot see.\n    """\n    try:\n        r = _backend().get(update_id)\n    except Exception as e:\n        return {"error": str(e)}\n    if not r:\n        return {"error": f"no chunk for update {update_id}"}\n    r = dict(r)\n    v = r.pop("vector", None)\n    r.pop("_distance", None)\n    if v is not None:\n        v = [float(x) for x in v]\n        r["dim"] = len(v)\n        r["norm"] = round(math.sqrt(sum(x * x for x in v)), 6)\n        r["vector_preview"] = [round(x, 5) for x in v[:preview_dims]]\n    try:\n        row = _con().execute("SELECT text FROM updates WHERE update_id = ?",\n                             (update_id,)).fetchone()\n        if row is None:\n            r["source"] = "MISSING - this chunk cites an update that is not on file"\n            r["matches_source"] = False\n        else:\n            r["source_text"] = row[0]\n            r["matches_source"] = (row[0] or "") == (r.get("text") or "")\n    except Exception:\n        pass\n    return r\n\n\ndef retrieval_trace(query: str, retrieve_n: int = RETRIEVE_N,\n                    rerank_n: int = RERANK_N, ro_number: str | None = None,\n                    uri: str | None = None) -> dict:\n    """Both stages of a real search, so the reranker\'s contribution is visible.\n\n    `search_updates` returns six passages and nothing about how they were chosen.\n    This runs the same two calls - the same query embedding, the same wide\n    retrieve, the same rerank - and keeps the intermediate stage, with each\n    passage\'s movement between the two.\n\n    It mirrors app/retrieval/index.py rather than sharing its code, so that it\n    can keep the stage that `search` throws away. test_review.py asserts the two\n    agree on the final citations; if they ever diverge, that test is what says so.\n    """\n    from app.nim.client import embed_query as nim_embed_query, rerank as nim_rerank\n    out: dict[str, Any] = {"query": query, "retrieve_n": retrieve_n,\n                           "rerank_n": rerank_n, "ro_number": ro_number}\n    b = _backend()\n    out.update({k: v for k, v in b.stats().items() if k in ("backend", "mode")})\n    try:\n        if not b.exists():\n            return {**out, "error": f"no index at {b.uri} - build it first"}\n    except Exception as e:\n        return {**out, "error": str(e)}\n\n    t0 = time.perf_counter()\n    try:\n        qv = nim_embed_query(query)\n    except Exception as e:\n        return {**out, "error": f"embedding failed - {type(e).__name__}: {e}"}\n    out["embed_ms"] = round((time.perf_counter() - t0) * 1000, 1)\n    out["query_dim"] = len(qv)\n\n    t1 = time.perf_counter()\n    try:\n        hits = b.search(qv, k=retrieve_n, ro_number=ro_number)\n    except Exception as e:\n        return {**out, "error": f"vector search failed - {type(e).__name__}: {e}"}\n    out["search_ms"] = round((time.perf_counter() - t1) * 1000, 1)\n\n    retrieved = []\n    for i, h in enumerate(hits):\n        retrieved.append({\n            "rank": i + 1, "update_id": h.get("update_id"),\n            "ro_number": h.get("ro_number"), "at": h.get("at"),\n            "by": h.get("staff_name") or h.get("staff_id"),\n            "vehicle": h.get("vehicle"), "text": h.get("text"),\n            "vector_score": h.get("vector_score")})\n    out["retrieved"] = retrieved\n\n    if not retrieved or rerank_n <= 0:\n        out["reranked"] = []\n        return out\n\n    t2 = time.perf_counter()\n    try:\n        ranked = nim_rerank(query, [r["text"] for r in retrieved], top_n=rerank_n)\n    except Exception as e:\n        out["rerank_error"] = f"{type(e).__name__}: {e}"\n        out["reranked"] = retrieved[:rerank_n]\n        return out\n    out["rerank_ms"] = round((time.perf_counter() - t2) * 1000, 1)\n\n    reranked = []\n    for new_rank, r in enumerate(ranked, 1):\n        src = dict(retrieved[r["index"]])\n        src["rerank_score"] = r["score"]\n        src["vector_rank"] = src.pop("rank")\n        src["rank"] = new_rank\n        src["moved"] = src["vector_rank"] - new_rank      # positive = promoted\n        reranked.append(src)\n    out["reranked"] = reranked\n\n    kept = {r["update_id"] for r in reranked}\n    out["promoted"] = [r for r in reranked if r["moved"] > 0]\n    out["dropped"] = [r for r in retrieved[:rerank_n] if r["update_id"] not in kept]\n    out["citations"] = [r["update_id"] for r in reranked]\n    return out',
     'store.py  the vector views read through the backend, and check text drift',
     skip_if='def _backend():')


