import hashlib, math, os, tempfile
bad = 0


def chk(name, ok, detail=""):
    global bad
    bad += (not ok)
    print(f"  {'ok     ' if ok else 'WRONG  '} {name}" + (f"  ({detail})" if detail else ""))


# A scratch Milvus and a scratch database: this must not touch the real ones.
os.environ["ASOIA_MILVUS_URI"] = os.path.join(tempfile.mkdtemp(), "m.db")
from app.retrieval import backend as B
B.reset()

print("\nthe backend:")
try:
    b = B.backend()
    st = b.stats()
    chk("milvus is the default", st["backend"] == "milvus", st["backend"])
    chk("a file uri means embedded", st["mode"] == "embedded", st["mode"])
    ok_server = B.MilvusBackend(uri="http://localhost:19530").mode == "server"
    chk("an http uri means a server", ok_server)
    chk("lancedb is still reachable", B.backend("lancedb").name == "lancedb")
    try:
        B.backend("redis")
        chk("an unknown backend is refused", False)
    except B.BackendError as e:
        chk("an unknown backend is refused", "not a store" in str(e))
except Exception as e:
    chk("the backend loads", False, f"{type(e).__name__}: {e}")
    b = None


def _v(s, d=16):
    h = hashlib.sha256(s.encode()).digest()
    v = [(h[i % 32] / 255.0) - 0.5 for i in range(d)]
    n = math.sqrt(sum(x * x for x in v)) or 1.0
    return [x / n for x in v]


if b is not None:
    try:
        b.create(dim=16)
        rows = [{"update_id": f"U{i}", "ro_number": f"RO-{i//3}", "staff_id": "E1",
                 "staff_name": "A", "at": f"2026-09-2{i%9}T10:00:00",
                 "shift": "MORNING", "text": f"chunk number {i}",
                 "vehicle": "V", "category": "C", "concern": "c", "vin": "X",
                 "vector": _v(f"c{i}")} for i in range(12)]
        b.upsert(rows)
        chk("upsert then count", b.count() == 12, str(b.count()))
        sc = b.scan()
        chk("scan drops the vector column", sc and "vector" not in sc[0])
        chk("get carries the vector", len(b.get("U3")["vector"]) == 16)
        chk("a missing id returns None", b.get("U999") is None)
        hits = b.search(_v("c5"), k=3)
        chk("search finds the exact match", hits[0]["update_id"] == "U5",
            hits[0]["update_id"])
        f = b.search(_v("c5"), k=5, ro_number="RO-0")
        chk("search filters by repair order",
            all(h["ro_number"] == "RO-0" for h in f), str(len(f)) + " hits")
        rows[0]["text"] = "changed"
        b.upsert([rows[0]])
        chk("upsert replaces rather than duplicates",
            b.count() == 12 and b.get("U0")["text"] == "changed")
        b.delete(["U1"])
        chk("delete removes one", b.count() == 11 and b.get("U1") is None)
        chk("sample_vectors returns vectors",
            len(b.sample_vectors(3)) == 3 and "vector" in b.sample_vectors(1)[0])
        # the released-collection trap
        b2 = B.MilvusBackend(uri=b.uri)
        chk("a fresh client loads the collection before reading",
            len(b2.scan()) == 11, f"{len(b2.scan())} rows from a new client")
    except Exception as e:
        chk("the milvus round trip", False, f"{type(e).__name__}: {str(e)[:120]}")

